export function KnowledgeBase({
  title = "{{title}}",
  placeholder = "{{placeholder}}",
  layout = "{{layout}}",
  accent = "{{accent}}",
  articleCount = {{articleCount}},
}) {
  const articles = [
    { tag: "Account", heading: "Resetting your password", body: "Step-by-step instructions to regain access to your account." },
    { tag: "Security", heading: "Setting up two-factor authentication", body: "Add an extra layer of protection to your login." },
    { tag: "Data", heading: "Exporting your data", body: "Download a full copy of your workspace in CSV or JSON." },
  ];
  const resultsStyle = {
    list: { display: "flex", flexDirection: "column", gap: 10 },
    grid: { display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 },
    compact: { display: "flex", flexDirection: "column", gap: 6 },
  }[layout] ?? {};
  return (
    <div style={{ font: "16px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, maxWidth: 420, borderRadius: 14, border: "1px solid #24143018" }}>
      <h2 style={{ margin: "0 0 12px", fontSize: 18, fontWeight: 600 }}>{title}</h2>
      <label style={{ display: "flex", alignItems: "center", gap: 8, background: "#fff", border: "1.5px solid #24143025", borderRadius: 10, padding: "8px 12px", marginBottom: 10 }}>
        <svg width="16" height="16" viewBox="0 0 20 20" aria-hidden="true" style={{ color: "#24143070", flexShrink: 0 }}><circle cx="9" cy="9" r="6" fill="none" stroke="currentColor" strokeWidth="1.6" /><line x1="13.2" y1="13.2" x2="18" y2="18" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" /></svg>
        <input type="search" placeholder={placeholder} aria-label={placeholder} style={{ border: "none", outline: "none", flex: 1, background: "transparent", font: "inherit" }} />
      </label>
      <p style={{ margin: "0 0 10px", fontSize: 12, color: "#24143099" }}>{articleCount} articles available</p>
      <ul style={{ listStyle: "none", margin: 0, padding: 0, ...resultsStyle }}>
        {articles.map((a) => (
          <li key={a.heading} style={{ padding: layout === "compact" ? "8px 10px" : 12, borderRadius: 10, border: "1px solid #24143014" }}>
            <span style={{ display: "inline-block", fontSize: 11, fontWeight: 600, padding: "2px 8px", borderRadius: 999, background: accent, color: "#241430" }}>{a.tag}</span>
            <h3 style={{ margin: "4px 0", fontSize: 14, fontWeight: 600 }}>{a.heading}</h3>
            {layout !== "compact" && <p style={{ margin: 0, fontSize: 12.5, color: "#241430b3" }}>{a.body}</p>}
          </li>
        ))}
      </ul>
    </div>
  );
}
